#include <sys/types.h>
#include <unistd.h>

#include "../include/gpsd.h"

static int verbose = 0;

struct map
{
    char *legend;
    unsigned char test[MAX_PACKET_LENGTH + 1];
    size_t testlen;
    int garbage_offset;
    int type;
};

/* *INDENT-OFF* */
static struct map singletests[] = {
    /* NMEA tests */
    {
        .legend = "NMEA packet with checksum (1)",
        .test = "$GPVTG,308.74,T,,M,0.00,N,0.0,K*68\r\n",
        .testlen = 36,
        .garbage_offset = 0,
        NMEA_PACKET,
    },
    {
        .legend = "NMEA packet with checksum (2)",
        .test = "$GPGGA,110534.994,4002.1425,N,07531.2585,W,0,00,50.0,"
                "172.7,M,-33.8,M,0.0,0000*7A\r\n",
        .testlen = 82,
        .garbage_offset = 0,
        .type = NMEA_PACKET,
    },
    {
        .legend = "NMEA packet with checksum and 4 chars of leading garbage",
        .test = "\xff\xbf\x00\xbf$GPVTG,308.74,T,,M,0.00,N,0.0,K*68\r\n",
        .testlen = 40,
        .garbage_offset = 4,
        .type = NMEA_PACKET,
    },
    {
        .legend = "NMEA packet without checksum",
        .test = "$STI,3\r\n",
        .testlen = 8,
        .garbage_offset = 0,
        .type = NMEA_PACKET,
    },
    {
        .legend = "NMEA packet with wrong checksum",
        .test = "$GPVTG,308.74,T,,M,0.00,N,0.0,K*28\r\n",
        .testlen = 36,
        .garbage_offset = 0,
        .type = BAD_PACKET,
    },
    {
        .legend = "NMEA interspersed packet",
        .test = "$GPZDA,112533.00,20,01,20$PTNTA,20000102173852,1,T4,"
                ",,6,1,0*32\r\n",
        .testlen = 64,
        .garbage_offset = 25,
        .type = NMEA_PACKET,
    },
    {
        .legend = "NMEA interrupted packet",
        .test = "$GPZDA,112533.00,20,01,2016,00,00*67\r\n$GPZDA,112533.00,20,"
                "01,20$PTNTA,20000102173852,1,T4,,,6,1,0*32\r\n16,00,00*67\r\n",
        .testlen = 115,
        .garbage_offset = 0,
        .type = NMEA_PACKET,
    },
    /* SiRF tests */
    {
        .legend = "SiRF WAAS version ID",
        .test = {
            0xA0, 0xA2, 0x00, 0x15,
            0x06, 0x06, 0x31, 0x2E, 0x32, 0x2E, 0x30, 0x44,
            0x4B, 0x49, 0x54, 0x31, 0x31, 0x39, 0x20, 0x53,
            0x4D, 0x00, 0x00, 0x00, 0x00,
            0x03, 0x82, 0xB0, 0xB3},
        .testlen = 29,
        .garbage_offset = 0,
        .type = SIRF_PACKET,
    },
    {
        .legend = "SiRF WAAS version ID with 3 chars of leading garbage",
        .test = {
            0xff, 0x00, 0xff,
            0xA0, 0xA2, 0x00, 0x15,
            0x06, 0x06, 0x31, 0x2E, 0x32, 0x2E, 0x30, 0x44,
            0x4B, 0x49, 0x54, 0x31, 0x31, 0x39, 0x20, 0x53,
            0x4D, 0x00, 0x00, 0x00, 0x00,
            0x03, 0x82, 0xB0, 0xB3},
        .testlen = 32,
        .garbage_offset = 3,
        .type = SIRF_PACKET,
    },
    {
        .legend = "SiRF WAAS version ID with wrong checksum",
        .test = {
            0xA0, 0xA2, 0x00, 0x15,
            0x06, 0x06, 0x31, 0x2E, 0x32, 0x2E, 0x30, 0x44,
            0x4B, 0x49, 0x54, 0x31, 0x31, 0x39, 0x20, 0x53,
            0x4D, 0x00, 0x00, 0x00, 0x00,
            0x03, 0x00, 0xB0, 0xB3},
        .testlen = 29,
        .garbage_offset = 0,
        .type = BAD_PACKET,
    },
    {
        .legend = "SiRF WAAS version ID with bad length",
        .test = {
            0xA0, 0xA2, 0xff, 0x15,
            0x06, 0x06, 0x31, 0x2E, 0x32, 0x2E, 0x30, 0x44,
            0x4B, 0x49, 0x54, 0x31, 0x31, 0x39, 0x20, 0x53,
            0x4D, 0x00, 0x00, 0x00, 0x00,
            0x03, 0x82, 0xB0, 0xB3},
        .testlen = 29,
        .garbage_offset = 0,
        .type = BAD_PACKET,
    },
    /* Zodiac tests */
    {
        .legend = "Zodiac binary 1000 Geodetic Status Output Message",
        .test = {
            0xff, 0x81, 0xe8, 0x03, 0x31, 0x00, 0x00, 0x00, 0xe8, 0x79,
            0x74, 0x0e, 0x00, 0x00, 0x24, 0x00, 0x24, 0x00, 0x04, 0x00,
